from pathlib import Path,PurePosixPath
import base64,hashlib,io,json,subprocess,sys,tarfile,time
PAYLOAD=''
EXPECTED=[{'member': 'tools/p26/cell05-shape-completion-20261127/complete_shape.py', 'bytes': 45345, 'sha256': 'dc75e4c6d56df8673a6551420f74015b0b75d1fec3fe62b544ef63bcc596a133'}, {'member': 'tools/p26/cell05-shape-completion-20261127/PINS.json', 'bytes': 25524, 'sha256': 'be4fc8f2064e9ba988a8eaed42b54831635eca9a297abf57bd08c08446b5be86'}, {'member': 'tools/p26/cell05-shape-completion-20261127/owned-audits/P2OriginalSaving19Geometry05ScalableShape.lean', 'bytes': 2720, 'sha256': 'e5106b4fcb2f8c166a26e9888e23e54b5435deb4dee50f89e27a7877bda43fd1'}, {'member': 'tools/p26/cell05-shape-completion-20261127/RECOVERY_BINDING.json', 'bytes': 967, 'sha256': '7425ce0a4d3c5907e55a74041f6f12456559f9d854a774fa648a16c2cd6f0f34'}, {'member': 'project/ImbalancedChen/P2OriginalSaving19Geometry05ScalableShape.lean', 'bytes': 7508, 'sha256': 'fd381d234ea1c9100d9248542273663df8b3042282326410a9fe8aaf961d90bb'}]
STAGE=Path('/workspace/p26-cell05-shape-completion-20261127-v1')
TOOL=STAGE/'tools/p26/cell05-shape-completion-20261127'
BINDING_SHA='7425ce0a4d3c5907e55a74041f6f12456559f9d854a774fa648a16c2cd6f0f34'
def need(v,message):
 if not v:raise ValueError(message)
def pin(p):
 b=p.read_bytes();return {'path':str(p),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
def encoded(v):return (json.dumps(v,indent=2)+'\n').encode()
def write_new(p,b):
 need(p.resolve()==p and not p.is_symlink(),'Noncanonical destination')
 with p.open('xb') as f:f.write(b)
raw=base64.b64decode(PAYLOAD,validate=True)
need(len(raw)==20444 and hashlib.sha256(raw).hexdigest()=='ad41ab5be692775904098661c4fb39687d6e78d97a3ee6823c84dfdd523a07cb','Deployment archive differs')
files={}
with tarfile.open(fileobj=io.BytesIO(raw),mode='r:xz') as t:
 for m in t:
  n=PurePosixPath(m.name);need(m.isfile() and not n.is_absolute() and '..' not in n.parts and m.name not in files,'Unsafe member')
  files[m.name]=t.extractfile(m).read()
need(set(files)=={r['member'] for r in EXPECTED},'Wrong deployment inventory')
for r in EXPECTED:
 b=files[r['member']];need(len(b)==r['bytes'] and hashlib.sha256(b).hexdigest()==r['sha256'],'Frozen payload differs')
need(STAGE.resolve()==STAGE and not STAGE.exists() and not STAGE.is_symlink(),'Stage exists; preserve prior files')
STAGE.mkdir()
for n,b in files.items():
 p=STAGE/n;p.parent.mkdir(parents=True,exist_ok=True);write_new(p,b)
write_new(STAGE/'DEPLOYMENT_BUNDLE.tar.xz',raw)
write_new(STAGE/'DEPLOYMENT_MANIFEST.json',encoded({'schema':'p26_shape_exact_deployment_v1','stage':str(STAGE),'files':EXPECTED,'binding_sha256':BINDING_SHA,'old_Lean_commands':0,'proof_commands_executed':0}))
print(json.dumps({'kind':'shape_deployed','stage':str(STAGE),'binding':pin(TOOL/'RECOVERY_BINDING.json'),'members':len(files),'proof_commands_executed':0}),flush=True)
argv=[sys.executable,'-I','-B',str(TOOL/'complete_shape.py'),'preflight','--recovery-binding-sha256',BINDING_SHA]
start=time.monotonic();out=STAGE/'PREFLIGHT.stdout';err=STAGE/'PREFLIGHT.stderr'
with out.open('xb') as o,err.open('xb') as e:proc=subprocess.run(argv,stdout=o,stderr=e,check=False,timeout=3300)
result={'schema':'p26_shape_preflight_process_v1','argv':argv,'exit_code':proc.returncode,'elapsed_seconds':time.monotonic()-start,'stdout':pin(out),'stderr':pin(err),'proof_commands_executed':0}
write_new(STAGE/'PREFLIGHT_PROCESS.json',encoded(result));print(json.dumps({'kind':'shape_preflight_finished',**result}),flush=True)
if proc.returncode:
 print(err.read_text(errors='replace')[-24000:],flush=True);sys.exit(proc.returncode)
v=json.loads(out.read_bytes());need(v['status']=='PASS_PREFLIGHT' and v['dependencies']==125 and v['accepted_existing_steps']==0 and v['proof_commands_executed']==0,'Unexpected preflight result')
print(json.dumps(v),flush=True)
